/*
  Терминал корабля: фосфорный экран, сканлайны, лёгкое дрожание яркости.
  Всё рисуется CSS — ни одной картинки, ни одного внешнего шрифта.
*/

:root {
  --phosphor: #7dff9b;
  --phosphor-dim: #3d8a52;
  --phosphor-faint: #1c3d27;
  --amber: #ffb347;
  --amber-dim: #8a5f26;
  --alert: #ff4d4d;
  --bg: #050a06;
  --panel: #0a140c;
  --panel-edge: #16301c;
  --light-square: #17301d;
  --dark-square: #0d1e11;

  --font: 'Consolas', 'DejaVu Sans Mono', 'Courier New', monospace;
  --board-max: min(72vh, 560px);
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  height: 100%;
  background: var(--bg);
  color: var(--phosphor);
  font-family: var(--font);
  font-size: 14px;
  letter-spacing: 0.04em;
  overflow: hidden;
}

/* Сканлайны и виньетка — поверх всего, но не перехватывают клики. */
body::after {
  content: '';
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 100;
  background:
    repeating-linear-gradient(
      to bottom,
      rgba(0, 0, 0, 0.22) 0px,
      rgba(0, 0, 0, 0.22) 1px,
      transparent 1px,
      transparent 3px
    ),
    radial-gradient(ellipse at center, transparent 55%, rgba(0, 0, 0, 0.55) 100%);
  animation: flicker 5.5s infinite steps(60);
}

@keyframes flicker {
  0%, 96%, 100% { opacity: 1; }
  97% { opacity: 0.93; }
